const config = $('Set workflow configuration').first().json;
const allowedCountries = new Set(['IT', 'DE', 'FR', 'NL', 'ES', 'GB', 'US', 'IE']);
const allowedPersonas = new Set(['founder_ceo', 'sales_leader', 'marketing_leader', 'ops_logistics', 'procurement', 'finance_cfo', 'tech_leader', 'hr_people', 'ecommerce_owner']);

const maxDomains = Number(config.max_domains_per_run);
const maxCharge = Number(config.max_total_charge_usd);

if (!allowedPersonas.has(config.persona)) {
  throw new Error(`Unsupported persona: ${config.persona}`);
}
if (!Number.isInteger(maxDomains) || maxDomains < 1 || maxDomains > 1000) {
  throw new Error('max_domains_per_run must be an integer from 1 to 1000');
}
if (!(maxCharge > 0)) {
  throw new Error('max_total_charge_usd must be greater than zero');
}

function cellToString(value) {
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (!value || typeof value !== 'object') return '';
  // Google Sheets / n8n hyperlink-ish payloads
  for (const key of ['text', 'label', 'displayValue', 'hyperlink', 'link', 'url', 'value']) {
    if (typeof value[key] === 'string' && value[key].trim()) return value[key];
  }
  if (Array.isArray(value) && value.length) return cellToString(value[0]);
  return '';
}

function normalizeDomain(value) {
  // Do not use the URL constructor: many n8n Code sandboxes throw
  // "URL is not defined", and a surrounding try/catch would mark every
  // domain as INVALID_INPUT before Apify is ever called.
  let raw = cellToString(value).trim().toLowerCase();
  if (!raw) return null;
  raw = raw.replace(/^\ufeff/, '').replace(/[\u200b-\u200d\ufeff]/g, '');
  raw = raw.replace(/^https?:\/\//, '').replace(/^\/\//, '');
  if (raw.includes('@')) raw = raw.split('@').pop();
  raw = raw.split('/')[0].split('?')[0].split('#')[0];
  raw = raw.replace(/:\d+$/, '');
  raw = raw.replace(/^www\./, '').replace(/\.$/, '');
  if (!raw || raw.length > 253 || !raw.includes('.')) return null;
  if (raw.includes(' ') || raw.includes('..')) return null;
  const labels = raw.split('.');
  if (labels.some((label) => !label || !/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(label))) return null;
  return raw;
}

const seen = new Set();
const validRows = [];
const invalidRows = [];
for (const { json } of $input.all()) {
  const status = cellToString(json.status).trim().toUpperCase();
  if (status && status !== 'READY') continue;
  const originalDomain = cellToString(json.domain).trim() || null;
  const normalized = normalizeDomain(json.domain);
  const country = cellToString(json.country).trim().toUpperCase();
  const sourceRow = json.row_number ?? json.rowNumber ?? null;
  if (!normalized) {
    invalidRows.push({
      domain: originalDomain,
      country: country || null,
      source_row: sourceRow,
      classification: 'INVALID_INPUT',
      error_message: 'Domain could not be normalized to a bare hostname',
    });
    continue;
  }
  if (country && !allowedCountries.has(country)) {
    invalidRows.push({
      domain: normalized,
      country,
      source_row: sourceRow,
      classification: 'INVALID_INPUT',
      error_message: `Country must be one of: ${[...allowedCountries].join(', ')}`,
    });
    continue;
  }
  if (seen.has(normalized)) {
    invalidRows.push({
      domain: normalized,
      country: country || null,
      source_row: sourceRow,
      classification: 'DUPLICATE_IN_BATCH',
      error_message: 'Duplicate domain in this batch',
    });
    continue;
  }
  seen.add(normalized);
  validRows.push({ domain: normalized, country: country || null, source_row: sourceRow });
  if (validRows.length >= maxDomains) break;
}

const batchId = `dmf-${$execution.id}`;
const actorDomains = validRows.map((row) => row.country ? { domain: row.domain, country: row.country } : row.domain);
return [{ json: {
  batch_id: batchId,
  execution_id: String($execution.id),
  started_at: $now.toISO(),
  persona: config.persona,
  valid_rows: validRows,
  invalid_rows: invalidRows,
  requested_domains: [...validRows.map((row) => row.domain), ...invalidRows.map((row) => row.domain).filter(Boolean)],
  actor_input: {
    domains: actorDomains,
    verifyEmails: true,
    aiDiscovery: true,
    includeGenericInbox: true,
    targetPersona: { mode: 'preset', preset: config.persona },
    mustHaveVerifiedEmail: true,
    identityStrictness: 'flag',
    pushEmptyResults: false
  }
} }];

const prepared = $('Prepare one Actor batch').first().json;
if (prepared.valid_rows.some((row) => row.source_row === null)) {
  throw new Error('Google Sheets input is missing row_number metadata');
}
return prepared.valid_rows.map((row) => ({ json: {
  row_number: row.source_row,
  status: 'IN_PROGRESS',
  batch_id: prepared.batch_id,
  apify_run_id: '',
  result_class: '',
  processed_at: '',
  error_message: ''
} }));

const failure = $('Format failed run log').first().json;
const prepared = $('Prepare one Actor batch').first().json;
return prepared.valid_rows
  .filter((row) => row.source_row !== null && row.source_row !== undefined)
  .map((row) => ({ json: {
    row_number: row.source_row,
    status: failure.error_class,
    batch_id: failure.batch_id,
    apify_run_id: failure.apify_run_id ?? '',
    result_class: '',
    processed_at: failure.finished_at,
    error_message: failure.error_message
  } }));

const prepared = $('Prepare one Actor batch').first().json;
const run = $json.data ?? $json;
if (!run.id) throw new Error('Apify start response did not include a run ID');
return [{ json: {
  ...prepared,
  apify_run_id: run.id,
  dataset_id: run.defaultDatasetId ?? null,
  apify_status: run.status ?? 'READY',
  poll_count: 0,
  apify_run_url: `https://console.apify.com/actors/runs/${run.id}`
} }];

const previous = $('Wait before status check').item.json;
const run = $json.data ?? $json;
return [{ json: {
  ...previous,
  apify_status: run.status ?? 'UNKNOWN',
  dataset_id: run.defaultDatasetId ?? previous.dataset_id ?? null,
  poll_count: (previous.poll_count ?? 0) + 1
} }];

const prepared = $('Prepare one Actor batch').first().json;
const runContext = $('Reconcile Apify status').first().json;
const rawItems = $input.all().flatMap(({ json }) => Array.isArray(json) ? json : (Array.isArray(json.data) ? json.data : [json]));
const byDomain = new Map(rawItems.filter((row) => row && typeof row.domain === 'string').map((row) => [row.domain.toLowerCase().replace(/^www\./, ''), row]));
const processedAt = $now.toISO();

function classify(row) {
  const dm = row.decision_maker ?? {};
  if (dm.email_sendable === true && ['suspect', 'incoherent'].includes(row.identity_status)) return 'REVIEW_IDENTITY';
  if (row.has_decision_maker === true && dm.email_sendable === true) return 'VERIFIED_DM_REVIEW';
  if (row.generic_email_sendable === true) return 'GENERIC_EMAIL_ONLY';
  if (row.has_contact === true) return 'PHONE_ONLY';
  if (row.has_decision_maker === true) return 'NAMED_NO_SENDABLE_EMAIL';
  return 'NO_BILLABLE_RESULT';
}

const results = prepared.valid_rows.map((requested) => {
  const row = byDomain.get(requested.domain) ?? { domain: requested.domain, country: requested.country, has_contact: false };
  const dm = row.decision_maker ?? {};
  return {
    source_row: requested.source_row,
    result_key: `${requested.domain}|${prepared.persona}`,
    batch_id: prepared.batch_id,
    apify_run_id: runContext.apify_run_id,
    domain: requested.domain,
    country: row.country ?? requested.country ?? null,
    persona: prepared.persona,
    classification: classify(row),
    full_name: dm.full_name ?? null,
    role: dm.role ?? null,
    seniority: dm.seniority ?? null,
    email: dm.email ?? null,
    email_sendable: dm.email_sendable === true,
    email_status: dm.email_status ?? null,
    email_quality: dm.email_quality ?? null,
    best_contact_email: row.best_contact_email ?? null,
    generic_email: row.generic_email ?? null,
    phone: dm.best_phone ?? dm.phone ?? null,
    linkedin_url: dm.linkedin_url ?? null,
    source: dm.source ?? null,
    confidence: dm.confidence ?? null,
    identity_status: row.identity_status ?? null,
    identity_flags: JSON.stringify(row.identity_flags ?? []),
    has_contact: row.has_contact === true,
    processed_at: processedAt
  };
});

for (const invalid of prepared.invalid_rows) {
  results.push({
    source_row: invalid.source_row,
    result_key: `${invalid.domain ?? `invalid-row-${invalid.source_row ?? 'unknown'}`}|${prepared.persona}`,
    batch_id: prepared.batch_id,
    apify_run_id: runContext.apify_run_id,
    domain: invalid.domain,
    country: invalid.country,
    persona: prepared.persona,
    classification: invalid.classification,
    email_sendable: false,
    identity_flags: '[]',
    has_contact: false,
    processed_at: processedAt,
    error_message: invalid.error_message ?? ''
  });
}

return results.map((json) => ({ json }));

return $input.all().map(({ json }) => {
  const { source_row: ignored, ...result } = json;
  return { json: result };
});

return $input.all()
  .filter(({ json }) => json.source_row !== null && json.source_row !== undefined)
  .map(({ json }) => ({ json: {
    row_number: json.source_row,
    status: json.classification,
    batch_id: json.batch_id,
    apify_run_id: json.apify_run_id ?? '',
    result_class: json.classification,
    processed_at: json.processed_at,
    error_message: json.error_message ?? ''
  } }));

const prepared = $('Prepare one Actor batch').first().json;
const source = $json;
let context = {};
try { context = $('Reconcile Apify status').first().json; } catch {}
try { if (!context.apify_run_id) context = $('Record started Apify run').first().json; } catch {}

const pollLimit = $('Set workflow configuration').first().json.max_poll_count;
let errorClass = 'REQUEST_FAILED';
if (!context.apify_run_id) errorClass = 'START_UNKNOWN';
else if (['FAILED', 'TIMED-OUT', 'ABORTED'].includes(source.apify_status)) errorClass = `ACTOR_${source.apify_status}`;
else if ((source.poll_count ?? context.poll_count ?? 0) >= pollLimit) errorClass = 'POLL_TIMEOUT';
else if (context.apify_status === 'SUCCEEDED') errorClass = 'DATASET_FETCH_FAILED';
else if (context.apify_run_id) errorClass = 'STATUS_FETCH_FAILED';

function extractErrorMessage(source) {
  const candidates = [
    source.error?.message,
    source.error?.description,
    source.error?.error,
    source.message,
    source.description,
    source.statusMessage,
    source.apify_status,
  ];
  for (const candidate of candidates) {
    if (typeof candidate === 'string' && candidate.trim()) return candidate.trim();
  }
  if (source.error && typeof source.error === 'object') {
    try { return JSON.stringify(source.error).slice(0, 500); } catch {}
  }
  try { return JSON.stringify(source).slice(0, 500); } catch {}
  return 'Unknown workflow error';
}
const message = extractErrorMessage(source);
return [{ json: {
  batch_id: prepared.batch_id,
  execution_id: prepared.execution_id,
  status: 'FAILED',
  started_at: prepared.started_at,
  finished_at: $now.toISO(),
  apify_run_id: context.apify_run_id ?? null,
  dataset_id: context.dataset_id ?? null,
  requested_domains: JSON.stringify(prepared.requested_domains),
  valid_domains: prepared.valid_rows.length,
  invalid_domains: prepared.invalid_rows.length,
  result_count: 0,
  verified_count: 0,
  review_count: 0,
  no_result_count: 0,
  poll_count: source.poll_count ?? context.poll_count ?? 0,
  error_class: errorClass,
  error_message: String(message).slice(0, 500),
  apify_run_url: context.apify_run_url ?? null
} }];
